using System.Text.Json;
using System.Text.Json.Nodes;
using System.Diagnostics;
using Microsoft.Web.WebView2.Core;
namespace VRMGalgame;
internal sealed partial class EditorWindow {
 private async Task RunGeometry52Smoke(){
  for(int i=0;i<600;i++){if(await web.CoreWebView2.ExecuteScriptAsync("Boolean(window.__vrmSmokeGeometry52&&window.editorCloseState?.().hasProject)")=="true")break;await Task.Delay(100);}
  async Task<JsonNode> Phase(string phase,string? suffix=null){
   await web.CoreWebView2.ExecuteScriptAsync("window.__geometryResult=null;window.__vrmSmokeGeometry52("+JsonSerializer.Serialize(phase)+").then(r=>window.__geometryResult=r).catch(e=>window.__geometryResult={error:e.message,stack:e.stack})");
   string result="null";for(int i=0;i<2400;i++){result=await web.CoreWebView2.ExecuteScriptAsync("window.__geometryResult");if(result!="null")break;await Task.Delay(50);}
   File.WriteAllText(smokeBase+".geometry-"+(suffix??phase)+".json",result);using(var shot=File.Create(smokeBase+".geometry-"+(suffix??phase)+".png"))await web.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,shot);var node=JsonNode.Parse(result)!;if(node["ok"]?.GetValue<bool>()!=true)throw new Exception(result);return node;
  }
  if(Environment.GetCommandLineArgs().Contains("--smoke-geometry52-reopen")){await Phase("reopen");editorCloseApproved=true;Close();return;}
  if(!Environment.GetCommandLineArgs().Contains("--smoke-geometry52-polish")){foreach(int width in new[]{1024,1500,2560}){await web.CoreWebView2.CallDevToolsProtocolMethodAsync("Emulation.setDeviceMetricsOverride",JsonSerializer.Serialize(new{width,height=850,deviceScaleFactor=1,mobile=false}));await Phase("ui","ui-"+width);}
  await web.CoreWebView2.CallDevToolsProtocolMethodAsync("Emulation.clearDeviceMetricsOverride","{}");
  await Phase("vehicle");for(int i=0;i<300&&!moduleWindows.ContainsKey("aircraft");i++)await Task.Delay(50);var child=moduleWindows["aircraft"];
  foreach(var size in new[]{new Size(1050,650),new Size(1500,900),new Size(2560,1529)}){await child.SmokeViewport52(size.Width,size.Height);string result=await child.Smoke("return await window.vehicleSmoke('palette52');",smokeBase+".palette-"+size.Width+".png");File.WriteAllText(smokeBase+".palette-"+size.Width+".json",result);if(!result.Contains("\"ok\":true"))throw new Exception(result);}child.CloseWithoutPrompt();}
  var connection=JsonSerializer.SerializeToNode(SetAgentEnabled(true))!;string session=connection["sessionId"]!.GetValue<string>();int serial=0;
  async Task<JsonNode> Agent(string tool,JsonNode? arguments=null,bool expectFailure=false){
   string input=smokeBase+".agent-input-"+(++serial)+".json";File.WriteAllText(input,(arguments??new JsonObject()).ToJsonString());
   var start=new ProcessStartInfo(Path.Combine(appDirectory,"VRMGalgame.Agent.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(string arg in new[]{"--session",session,"--call",tool,"--input",input})start.ArgumentList.Add(arg);
   using var process=Process.Start(start)!;var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();var finished=process.WaitForExitAsync();while(await Task.WhenAny(finished,Task.Delay(10000))!=finished){File.WriteAllText(smokeBase+".agent-progress.json",await web.CoreWebView2.ExecuteScriptAsync("window.__agentTrace52"));}await finished;string output=await stdout;var reply=JsonNode.Parse(output)!;if((reply["ok"]?.GetValue<bool>()==true)==expectFailure)throw new Exception(tool+": "+output+await stderr);return expectFailure?reply:reply["data"]!;
  }
  JsonObject HideGround(JsonNode created)=>new(){["op"]="update",["nodeId"]=created["environment"]!["nodes"]!.AsArray().First(n=>n?["kind"]?.GetValue<string>()=="ground")!["id"]!.DeepClone(),["patch"]=new JsonObject{["visible"]=false}};
  JsonObject WaterNode(JsonNode plan){var node=plan["water"]!.DeepClone().AsObject();node["op"]="add";node["kind"]="water";node["name"]="场景水面";return node;}
  try{
   if(Environment.GetCommandLineArgs().Contains("--smoke-geometry52-polish")){
    var p=await Agent("get_project");JsonNode current=p;
    foreach(var item in new[]{("Agent几何体港口","plan","environment"),("Agent花园住宅","plan-garden","garden")}){
     string id=p["environments"]!.AsArray().First(e=>e?["name"]?.GetValue<string>()==item.Item1)!["id"]!.GetValue<string>();var polishPlan=await Phase(item.Item2);await Agent("open_environment",new JsonObject{["environmentId"]=id});var polishScene=await Agent("get_environment",new JsonObject{["environmentId"]=id});var batch=polishScene["environment"]!["nodes"]!.AsArray().First(n=>n?["kind"]?.GetValue<string>()=="geometryBatch")!;
     var polishBuilt=await Agent("build_environment_geometry",new JsonObject{["environmentId"]=id,["mode"]="replace",["nodeId"]=batch["id"]!.DeepClone(),["expectedRevision"]=current["revision"]!.DeepClone(),["expectedEnvironmentRevision"]=polishScene["environment"]!["revision"]!.DeepClone(),["gridSize"]=polishPlan["gridSize"]!.DeepClone(),["primitives"]=polishPlan["primitives"]!.DeepClone()});
     var water=polishScene["environment"]!["nodes"]!.AsArray().First(n=>n?["kind"]?.GetValue<string>()=="water")!;current=await Agent("edit_environment",new JsonObject{["environmentId"]=id,["expectedRevision"]=polishBuilt["revision"]!.DeepClone(),["expectedEnvironmentRevision"]=polishBuilt["environmentRevision"]!.DeepClone(),["operations"]=new JsonArray(new JsonObject{["op"]="settings",["camera"]=polishPlan["camera"]!.DeepClone()},new JsonObject{["op"]="update",["nodeId"]=water["id"]!.DeepClone(),["patch"]=polishPlan["water"]!.DeepClone()})});
     var captured=await Agent("capture_environment",new JsonObject{["environmentId"]=id,["view"]="game"});if(captured["image"]?["mimeType"]?.GetValue<string>()!="image/png")throw new Exception("MCP截图没有返回图片");File.WriteAllBytes(smokeBase+"."+item.Item3+"-mcp.png",Convert.FromBase64String(captured["image"]!["data"]!.GetValue<string>()));File.WriteAllText(smokeBase+"."+item.Item3+"-mcp.json",JsonSerializer.Serialize(new{ok=true,captureEnvironment=true,replaceGeometry=true,waterAdjusted=true}));
     string polishCheck=await environmentWindow!.Geometry52Smoke(smokeBase+"."+item.Item3+"-geometry.png");File.WriteAllText(smokeBase+"."+item.Item3+"-geometry.json",polishCheck);if(!polishCheck.Contains("\"ok\":true"))throw new Exception(polishCheck);
    }
    await Phase("stage");await Agent("save",new JsonObject{["expectedRevision"]=current["revision"]!.DeepClone()});WriteArchive(projectDirectory!,smokeBase+".vrmg");File.WriteAllText(smokeBase+".geometry-export.json",JsonSerializer.Serialize(new{ok=true,exported=ExportGame("Agent几何体场景_0.0.52")}));environmentWindow!.CloseWithoutPrompt();editorCloseApproved=true;Close();return;
   }
   var caps=await Agent("get_capabilities");if(caps["agentSceneGeometry"]?["agentOnly"]?.GetValue<bool>()!=true)throw new Exception("MCP能力未注册");File.WriteAllText(smokeBase+".capabilities.json",JsonSerializer.Serialize(new{ok=true,geometry=caps["agentSceneGeometry"]}));
   var plan=await Phase("plan");var created=await Agent("create_environment",new JsonObject{["name"]="Agent几何体港口",["expectedRevision"]=caps["revision"]!.DeepClone()});string envId=created["environment"]!["id"]!.GetValue<string>();
   var build=new JsonObject{["environmentId"]=envId,["expectedRevision"]=created["revision"]!.DeepClone(),["expectedEnvironmentRevision"]=0,["name"]=plan["name"]!.DeepClone(),["gridSize"]=plan["gridSize"]!.DeepClone(),["primitives"]=plan["primitives"]!.DeepClone()};
   var refused=await Agent("build_environment_geometry",build,true);File.WriteAllText(smokeBase+".closed-editor.json",JsonSerializer.Serialize(new{ok=true,rejected=true,error=refused["error"]}));
   await Agent("open_environment",new JsonObject{["environmentId"]=envId});for(int i=0;i<300&&environmentWindow==null;i++)await Task.Delay(50);
   var built=await Agent("build_environment_geometry",build);string nodeId=built["nodeId"]!.GetValue<string>();File.WriteAllText(smokeBase+".geometry-build.json",JsonSerializer.Serialize(new{ok=true,result=built}));
   var page=await Agent("get_environment_geometry",new JsonObject{["environmentId"]=envId,["nodeId"]=nodeId,["limit"]=3});string firstId=page["primitives"]![0]!["id"]!.GetValue<string>(),originalColor=page["primitives"]![0]!["color"]!.GetValue<string>();
   var edit=await Agent("build_environment_geometry",new JsonObject{["environmentId"]=envId,["expectedRevision"]=built["revision"]!.DeepClone(),["expectedEnvironmentRevision"]=built["environmentRevision"]!.DeepClone(),["mode"]="update",["nodeId"]=nodeId,["primitives"]=new JsonArray(new JsonObject{["id"]=firstId,["color"]="#3e91b5"})});
   var undo=await Agent("undo",new JsonObject{["expectedRevision"]=edit["revision"]!.DeepClone()});var restored=await Agent("get_environment_geometry",new JsonObject{["environmentId"]=envId,["nodeId"]=nodeId,["limit"]=1});if(restored["primitives"]![0]!["color"]!.GetValue<string>()!=originalColor)throw new Exception("几何体不能撤销");var redo=await Agent("redo",new JsonObject{["expectedRevision"]=undo["revision"]!.DeepClone()});File.WriteAllText(smokeBase+".geometry-undo.json",JsonSerializer.Serialize(new{ok=true,paging=true,individualColor=true,undoRedo=true}));
   var scene=await Agent("get_environment",new JsonObject{["environmentId"]=envId});var configured=await Agent("edit_environment",new JsonObject{["environmentId"]=envId,["expectedRevision"]=redo["revision"]!.DeepClone(),["expectedEnvironmentRevision"]=scene["environment"]!["revision"]!.DeepClone(),["operations"]=new JsonArray(new JsonObject{["op"]="settings",["camera"]=plan["camera"]!.DeepClone(),["background"]="#b7d6e6",["lighting"]=new JsonObject{["color"]="#fff1d3",["intensity"]=2.4,["ambientIntensity"]=1.2}},HideGround(created),WaterNode(plan))});
   var project=await Agent("get_project");string actId=project["acts"]!.AsArray().First(a=>a?["kind"]?.GetValue<string>()=="act")!["id"]!.GetValue<string>();var linked=await Agent("set_environment_reference",new JsonObject{["target"]="act",["actId"]=actId,["environmentId"]=envId,["expectedRevision"]=configured["revision"]!.DeepClone()});
   string check=await environmentWindow!.Geometry52Smoke(smokeBase+".environment-geometry.png");File.WriteAllText(smokeBase+".environment-geometry.json",check);if(!check.Contains("\"ok\":true"))throw new Exception(check);
   var gardenPlan=await Phase("plan-garden");var gardenCreated=await Agent("create_environment",new JsonObject{["name"]="Agent花园住宅",["expectedRevision"]=linked["revision"]!.DeepClone()});string gardenId=gardenCreated["environment"]!["id"]!.GetValue<string>();
   await Agent("open_environment",new JsonObject{["environmentId"]=gardenId});var gardenBuilt=await Agent("build_environment_geometry",new JsonObject{["environmentId"]=gardenId,["expectedRevision"]=gardenCreated["revision"]!.DeepClone(),["expectedEnvironmentRevision"]=0,["name"]=gardenPlan["name"]!.DeepClone(),["gridSize"]=gardenPlan["gridSize"]!.DeepClone(),["primitives"]=gardenPlan["primitives"]!.DeepClone()});File.WriteAllText(smokeBase+".garden-build.json",JsonSerializer.Serialize(new{ok=true,result=gardenBuilt}));
   var gardenConfigured=await Agent("edit_environment",new JsonObject{["environmentId"]=gardenId,["expectedRevision"]=gardenBuilt["revision"]!.DeepClone(),["expectedEnvironmentRevision"]=gardenBuilt["environmentRevision"]!.DeepClone(),["operations"]=new JsonArray(new JsonObject{["op"]="settings",["camera"]=gardenPlan["camera"]!.DeepClone(),["background"]="#c9dfd7",["lighting"]=new JsonObject{["color"]="#fff0d1",["intensity"]=2.4,["ambientIntensity"]=1.0}},HideGround(gardenCreated),WaterNode(gardenPlan))});
   string gardenCheck=await environmentWindow!.Geometry52Smoke(smokeBase+".garden-geometry.png");File.WriteAllText(smokeBase+".garden-geometry.json",gardenCheck);if(!gardenCheck.Contains("\"ok\":true"))throw new Exception(gardenCheck);environmentWindow.CloseWithoutPrompt();
   await Phase("stage");var saved=await Agent("save",new JsonObject{["expectedRevision"]=gardenConfigured["revision"]!.DeepClone()});File.WriteAllText(smokeBase+".geometry-save.json",JsonSerializer.Serialize(new{ok=true,saved}));WriteArchive(projectDirectory!,smokeBase+".vrmg");File.WriteAllText(smokeBase+".geometry-export.json",JsonSerializer.Serialize(new{ok=true,exported=ExportGame("Agent几何体场景_0.0.52")}));
  }finally{StopAgentBridge();}
  editorCloseApproved=true;Close();
 }
}
